b'```
class L2Loss(Layer):

  def __init__(self, in_layers=None, **kwargs):
    super(L2Loss, self).__init__(in_layers, **kwargs)
    try:
      shape1 = self.in_layers[0].shape
      shape2 = self.in_layers[1].shape
      if shape1[0] is None:
        self._shape = (parent_shape[1],)
      else:
        self._shape = (parent_shape[0],)
    except:
      pass

  def create_tensor(self, in_layers=None, set_tensors=True, **kwargs):
    inputs = self._get_input_tensors(in_layers, True)
    guess, label = inputs[0], inputs[1]
    out_tensor = tf.reduce_mean(
        tf.square(guess - label), axis=list(range(1, len(label._shape))))
    if set_tensors:
      self.out_tensor = out_tensor
    return out_tensor
```
reduce_mean should be reduce_sum, same applies to L1Loss. This actually matters for Product sum.'

b'Looking through the code for the scaffold splitter we will always under fill the training set and over fill the test set based on granularity of the scaffold clusters.  This split has (2998, 708) for 3706 compounds so no compounds are missing.

```python
def create_scaffold_indices(pdbbind_dir, base_dir):

  frac_train = 0.8
  frac_valid = 0.0

  scaffolds = {}
  y = np.array([0 for val in ids])
  w = np.ones_like(y)
  for ind, pdb_code in enumerate(ids):
    print("Processing %s" % str(pdb_code))
    pdb_subdir = os.path.join(pdbbind_dir, pdb_code)
    mol = compute_ligand_mol(pdb_subdir, pdb_code)
    if mol is not None:
      engine = dc.utils.ScaffoldGenerator(include_chirality=False)
      scaffold = engine.get_scaffold(mol)
      if scaffold not in scaffolds:
        scaffolds[scaffold] = [ind]
      else:
        scaffolds[scaffold].append(ind)
    else:
      print(pdb_code)

  # Sort from largest to smallest scaffold sets
  scaffolds = {key: sorted(value) for key, value in scaffolds.items()}
  scaffold_sets = [
      scaffold_set
      for (scaffold, scaffold_set) in sorted(
          scaffolds.items(), key=lambda x: (len(x[1]), x[1][0]), reverse=True)
  ]
  train_cutoff = frac_train * len(y)
  valid_cutoff = (frac_train + frac_valid) * len(y)
  train_inds, valid_inds, test_inds = [], [], []
  for scaffold_set in scaffold_sets:
    if len(train_inds) + len(scaffold_set) > train_cutoff:
      if len(train_inds) + len(valid_inds) + len(scaffold_set) > valid_cutoff:
        test_inds += scaffold_set
      else:
        valid_inds += scaffold_set
    else:
      train_inds += scaffold_set
  return train_inds, valid_inds, test_inds
```
The scaffold split does not look at the Y values at all when doing the split.  This is definitely an argument to improve the scaffold splitter to some sort of stratified scaffold splitter.

I agree that it is suboptimal for a high affinity compounds to be missing from the test set.

